world node {
    use aap:caps/types@0.1.0.{run-info, subscription-list};

    import aap:caps/state-read@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(info: run-info) -> subscription-list;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_read};

struct Node;

/// Percent-encode a query component (RFC 3986 unreserved characters pass through).
fn encode_query(s: &str) -> String {
    s.bytes()
        .map(|b| match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                (b as char).to_string()
            }
            _ => format!("%{:02X}", b),
        })
        .collect()
}

/// Platform-approved enrichment: one fetch per call. Its result does not feed
/// the output, and a failed transport is ignored so the output is unchanged.
/// RunInfo carries no text field, so the run date is the query input.
fn enrich(date: &str) {
    let url = format!(
        "https://metadata.internal.example/enrich?q={}",
        encode_query(date)
    );
    let _ = http_client::fetch(&url);
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        enrich(&info.date);

        // No panics: a trap is not a valid output. If the 'urls' key is absent
        // or holds no non-empty lines, the output is an empty list rather than
        // a crash.
        let urls: Vec<String> = match state_read::get("urls") {
            Some(raw) => raw
                .split('\n')
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
